import { useEffect,useState } from 'react'
import api from '../../services/api'
import LoadingSpinner from '../../components/LoadingSpinner'
const next={PENDING:'CONFIRMED',CONFIRMED:'PREPARING',PREPARING:'READY_FOR_PICKUP'}
export default function VendorOrders(){const [orders,setOrders]=useState(null);const load=()=>api.get('/api/vendor/orders').then(({data})=>setOrders(data));useEffect(load,[]);async function advance(order){await api.patch(`/api/vendor/orders/${order.id}/status`,{status:next[order.status]});load()}if(!orders)return <LoadingSpinner/>;return <><span className="section-kicker">Fulfilment</span><h1 className="vendor-title">Orders</h1><div className="vendor-orders">{orders.length?orders.map(order=><div className="vendor-order" key={order.id}><div><strong>#{order.order_number}</strong><small>{order.items.map(i=>`${i.item_name} x ${i.quantity}`).join(', ')}</small><small>Payment: {order.payment_method.replaceAll('_',' ')}</small></div><span className="order-status">{order.status}</span>{next[order.status]&&<button className="auth-submit" onClick={()=>advance(order)}>{order.status==='PENDING'?'Accept Order':'Move to '+next[order.status].replaceAll('_',' ')}</button>}</div>):<p>No vendor orders yet.</p>}</div></>}
